-- Fictional, opt-in fixtures. Reapplying never resets edited business data.
DO $$
DECLARE
  configuration jsonb := '{"schema_version":1,"businesses":{"rental":{"stages":["intake","inspection"],"transitions":{"intake":["inspection"]},"record_kinds":{"inspection":{"fields":{"odometer":{"type":"integer","minimum":0,"maximum":1000000000,"required":true},"fuel_level":{"type":"number","minimum":0,"maximum":100},"notes":{"type":"string","max_length":2000,"nullable":true},"inspected":{"type":"boolean"}}}}}}}'::jsonb;
BEGIN
  -- Serialize fixture installation when two developers run it concurrently.
  PERFORM pg_advisory_xact_lock(618273910);
  IF EXISTS (SELECT 1 FROM app.tenants WHERE id = '00000000-0000-0000-0000-000000000001') THEN
    RETURN;
  END IF;
  UPDATE app.configuration_versions SET status='published',published_by=created_by_staff,published_at=now()
    WHERE id IN ('00000000-0000-0000-0000-000000001001','00000000-0000-0000-0000-000000002001');
  UPDATE app.tenants SET status='active' WHERE id IN ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002');
END $$;
